const origin='http://127.0.0.1:18917',output=process.env.INCIDENT_QA_OUTPUT||'/Users/toozservis/Developer/evidence-admin-incidents-20261105/web-evidence';
(async()=>{const setup=await(await fetch(origin+'/qa/setup')).json(),checks=[],errors=[],browser=await chromium.launch({channel:'chrome',headless:true});let context,page;
 async function open(){if(context)await context.close();context=await browser.newContext({viewport:{width:390,height:844}});await context.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());await context.addInitScript(jwt=>{sessionStorage.setItem('adminAccessToken',jwt);sessionStorage.setItem('adminRole','admin');},setup.web.users.admin.jwt);page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto(origin+'/web_admin/index.html#incidents');await page.locator('#incident-search').fill('web-user@example.com');await page.locator('#incident-filter-state').selectOption('all');await page.locator('#incident-list').getByRole('button',{name:/Otevřít případ/}).first().click();await page.getByRole('heading',{name:'Stav řešení',exact:true}).waitFor();}
 try{
  await open();await page.route('**/incidents/*/diagnostic',r=>r.fulfill({json:{redacted:false,format:'text/plain',text:'PRIVATE-NOT-REDACTED'}}),{times:1});await page.getByRole('button',{name:'Připravit diagnostiku pro sdílení',exact:true}).click();await page.getByText('Server nevrátil bezpečně připravenou diagnostiku. Nic nebylo zkopírováno.',{exact:true}).waitFor();assert.equal(await page.locator('pre.incident-diagnostic').count(),0);assert.equal(await page.getByRole('button',{name:'Zkopírovat diagnostiku',exact:true}).count(),0);assert(!((await page.locator('body').innerText()).includes('PRIVATE-NOT-REDACTED')));checks.push('Unredacted response cannot be displayed/copied/downloaded');
  await open();let release,seen;const pending=new Promise(resolve=>release=resolve),started=new Promise(resolve=>seen=resolve);await page.route('**/incidents/*/diagnostic',async r=>{seen();await pending;try{await r.fulfill({json:{redacted:true,format:'text/plain',text:'LATE-ACCOUNT-DIAGNOSTIC'}})}catch{}});await page.getByRole('button',{name:'Připravit diagnostiku pro sdílení',exact:true}).click();await started;await page.evaluate(jwt=>AdminBrowserSession.set(jwt,'admin'),setup.ios.users.admin.jwt);release();await page.locator('dialog.incident-dialog').waitFor({state:'detached'});assert(!((await page.locator('body').innerText()).includes('LATE-ACCOUNT-DIAGNOSTIC')));checks.push('Late response after actor-generation change never renders and dialog closes');
  await open();await page.evaluate(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async()=>{throw new DOMException('Denied','NotAllowedError')}}}));await page.getByRole('button',{name:'Připravit diagnostiku pro sdílení',exact:true}).click();await page.locator('pre.incident-diagnostic').waitFor();await page.getByRole('button',{name:'Zkopírovat diagnostiku',exact:true}).click();const fallback=page.getByLabel('Diagnostika k ručnímu zkopírování',{exact:true});await fallback.waitFor();assert(await fallback.evaluate(n=>n.readOnly&&n.selectionEnd-n.selectionStart===n.value.length));checks.push('Clipboard denied: selected read-only fallback available without external send');
  await open();await page.locator('dialog.incident-dialog header button').click();await page.route('**/incidents/*',async r=>{if(r.request().method()!=='GET'||!/^\/admin-api\/control-center\/incidents\/\d+$/.test(new URL(r.request().url()).pathname))return r.continue();const response=await r.fetch(),data=await response.json();data.title='<img src=x onerror=window.caseXSS=true>';data.diagnosis.suggested_actions.push({code:'execute',label:'Run remote repair',target:'https://example.invalid/run'});await r.fulfill({json:data});},{times:1});await page.locator('#incident-list').getByRole('button',{name:/Otevřít případ/}).first().click();await page.getByText('<img src=x onerror=window.caseXSS=true>',{exact:true}).waitFor();assert.equal(await page.evaluate(()=>window.caseXSS),undefined);assert.equal(await page.getByRole('button',{name:'Run remote repair'}).count(),0);assert.equal(await page.locator('dialog.incident-dialog img').count(),0);checks.push('Server strings render as text; arbitrary suggested URLs are not actionable');
  assert.deepEqual(errors,[]);fs.writeFileSync(path.join(output,'security-result.json'),JSON.stringify({status:'PASS',date:new Date().toISOString(),checks,limits:['Fault injection for delayed and malformed responses; real production session provider and UI']},null,2));console.log('PASS '+checks.length+' browser safety scenarios');
 }catch(error){await page?.screenshot({path:path.join(output,'security-failure.png'),fullPage:true});throw error;}finally{await context?.close();await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1});
